  {{ super() }}
  <style>
    /* Side Nav Styles */
    body, html {
      height: 100%;
      overflow-x: hidden;
    }

    .wrapper {
      display: flex;
      width: 100%;
      align-items: stretch;
      min-height: 100vh;
    }

    #sidebar {
      min-width: 250px;
      max-width: 250px;
      background: #212529;
      color: #fff;
      transition: all 0.3s;
