      padding: 20px;
      background: #1a1d20;
    }

    #sidebar ul.components {
      padding: 20px 0;
      border-bottom: 1px solid #47748b;
    }

    #sidebar ul li a {
      padding: 10px 20px;
      font-size: 1.1em;
      display: block;
      color: #adb5bd;
      text-decoration: none;
    }

    #sidebar ul li a:hover {
      color: #fff;
      background: #343a40;
    }

    #sidebar ul li.active > a {
      color: #fff;
      background: #007bff;
    }

    #content {
      width: 100%;
      padding: 20px;
      background: #f8f9fa;
    }

